/* sparrow-pico model `rover`, generated by training/pico_compile.py. No dependencies.
 * Unofficial community project. Not an AWS or Strands product. */
#pragma once
#include <math.h>

typedef enum { ROVER_PATH_CLEAR, ROVER_PATH_BLOCKED, ROVER_PATH_CROWDED, ROVER_PATH_WET_FLOOR } rover_path_t;
typedef struct {
    float battery; /* % */
    float front_obstacle_m;
    float goal_m;
    rover_path_t path;
    int carrying_load;
} rover_state;

#define ROVER_N_IN 8
static inline void rover_features(const rover_state *s, float *x) {
    int i = 0;
    x[i++] = (s->battery - (0.0f)) * (0.01f);
    x[i++] = (s->front_obstacle_m - (0.0f)) * (0.125f);
    x[i++] = (s->goal_m - (0.0f)) * (0.016666666666666666f);
    for (int k = 0; k < 4; k++) x[i++] = ((int)s->path == k) ? 1.f : 0.f;
    x[i++] = s->carrying_load ? 1.f : 0.f;
    (void)i;
}

#ifndef SPARROW_PICO_KERNEL
#define SPARROW_PICO_KERNEL 1  /* 0 simple, 1 four accumulators, 2 skip zero inputs */
#endif
static inline void sparrow_pico_dense(const float *w, const float *b, const float *x, int n_in, int n_out,
                                      int relu, float *y) {
#if SPARROW_PICO_KERNEL == 2
    /* inputs after a ReLU are often 0: skip them. Same arithmetic as the simple kernel, reordered. */
    int nz[64], n = 0;
    for (int i = 0; i < n_in; i++) if (x[i] != 0.f) nz[n++] = i;
    for (int o = 0; o < n_out; o++) {
        const float *r = w + o * n_in;
        float a = b[o];
        for (int j = 0; j < n; j++) a += r[nz[j]] * x[nz[j]];
        y[o] = relu && a < 0 ? 0 : a;
    }
#elif SPARROW_PICO_KERNEL == 1
    /* four independent sums hide the FPU's multiply-add latency */
    for (int o = 0; o < n_out; o++) {
        const float *r = w + o * n_in;
        float a0 = b[o], a1 = 0, a2 = 0, a3 = 0;
        int i = 0;
        for (; i + 3 < n_in; i += 4) {
            a0 += r[i] * x[i]; a1 += r[i + 1] * x[i + 1]; a2 += r[i + 2] * x[i + 2]; a3 += r[i + 3] * x[i + 3];
        }
        for (; i < n_in; i++) a0 += r[i] * x[i];
        float a = (a0 + a1) + (a2 + a3);
        y[o] = relu && a < 0 ? 0 : a;
    }
#else
    for (int o = 0; o < n_out; o++) {
        float a = b[o];
        for (int i = 0; i < n_in; i++) a += w[o * n_in + i] * x[i];
        y[o] = relu && a < 0 ? 0 : a;
    }
#endif
}

