#define ROVER_ACTION_N 5
/* raw scores; the largest is the answer */
static inline void rover_action_logits(const rover_state *s, float *out) {
    float x[ROVER_N_IN], h0[16], h1[16];
    rover_features(s, x);
    sparrow_pico_dense(rover_action_w0, rover_action_b0, x, ROVER_N_IN, 16, 1, h0);
    sparrow_pico_dense(rover_action_w1, rover_action_b1, h0, 16, 16, 1, h1);
    sparrow_pico_dense(rover_action_w2, rover_action_b2, h1, 16, 5, 0, out);
}
/* index of the chosen option, without the softmax */
static inline int rover_action_argmax(const rover_state *s) {
    float l[5];
    int b = 0;
    rover_action_logits(s, l);
    for (int i = 1; i < 5; i++) if (l[i] > l[b]) b = i;
    return b;
}
/* probabilities over the options */
static inline void rover_action(const rover_state *s, float *probs) {
    float m = -1e30f, z = 0;
    rover_action_logits(s, probs);
    for (int i = 0; i < 5; i++) if (probs[i] > m) m = probs[i];
    for (int i = 0; i < 5; i++) z += (probs[i] = expf(probs[i] - m));
    for (int i = 0; i < 5; i++) probs[i] /= z;
}
