/* raw scores; the largest is the answer */
static inline void rover_need_charge_logits(const rover_state *s, float *out) {
    float x[ROVER_N_IN], h0[16], h1[16];
    rover_features(s, x);
    sparrow_pico_dense(rover_need_charge_w0, rover_need_charge_b0, x, ROVER_N_IN, 16, 1, h0);
    sparrow_pico_dense(rover_need_charge_w1, rover_need_charge_b1, h0, 16, 16, 1, h1);
    sparrow_pico_dense(rover_need_charge_w2, rover_need_charge_b2, h1, 16, 2, 0, out);
}
/* index of the chosen option, without the softmax */
static inline int rover_need_charge_argmax(const rover_state *s) {
    float l[2];
    int b = 0;
    rover_need_charge_logits(s, l);
    for (int i = 1; i < 2; i++) if (l[i] > l[b]) b = i;
    return b;
}
/* probabilities over the options */
static inline void rover_need_charge(const rover_state *s, float *probs) {
    float m = -1e30f, z = 0;
    rover_need_charge_logits(s, probs);
    for (int i = 0; i < 2; i++) if (probs[i] > m) m = probs[i];
    for (int i = 0; i < 2; i++) z += (probs[i] = expf(probs[i] - m));
    for (int i = 0; i < 2; i++) probs[i] /= z;
}
